function SceneLocation({image}){const [sub,setSub]=useState('analysis');return <section><nav className="scene-subtabs" aria-label="장소AI 화면"><button className={sub==='analysis'?'active':''} onClick={()=>setSub('analysis')}>AI 분석</button><button className={sub==='candidates'?'active':''} onClick={()=>setSub('candidates')}>장소 후보함</button></nav>{sub==='analysis'?<PlaceAnalysis initialImage={image} onSaved={()=>setSub('candidates')}/>:<ScenePlaces/>}</section>}
function ClosetGapTabs({userId}){const [sub,setSub]=useState('gap');return <><div className="closet-inbox-tabs" style={{marginBottom:18}}><button className={sub==='gap'?'active':''} onClick={()=>setSub('gap')}>갭분석</button><button className={sub==='checklist'?'active':''} onClick={()=>setSub('checklist')}>체크리스트</button></div>{sub==='gap'?<GapAnalysis userId={userId}/>:<ClosetChecklists userId={userId}/>}</>}
