function Studio({value,items,urls,references,referenceUrls,realizationRefs,initialReference,onBack,onSave,onDuplicate,onDelete,busy}){const [data,setData]=useState({...value,elements:(value.elements||[]).map(x=>({...x}))}),[mode,setMode]=useState('slots'),[filter,setFilter]=useState('전체'),[selected,setSelected]=useState(null),[addOpen,setAddOpen]=useState(false),[refPicker,setRefPicker]=useState(false),[activeReference,setActiveReference]=useState(initialReference||null),[detailsOpen,setDetailsOpen]=useState(false),[moreOpen,setMoreOpen]=useState(false),[allSlots,setAllSlots]=useState(false),[pickerSearch,setPickerSearch]=useState(''),[exportBusy,setExportBusy]=useState(false);const board=useRef(null),drag=useRef(null);const elements=data.elements||[];const selectedEl=elements.find(e=>e.eid===selected);const joined=elements.map(e=>({...e,item:items.find(i=>i.id===e.item_id)}));function patch(up){setData(p=>({...p,...up}))}function updateEl(id,patchEl){setData(p=>({...p,elements:(p.elements||[]).map(e=>e.eid===id?{...e,...patchEl}:e)}))}function add(i){patch({elements:[...elements,makeElement(i,elements.length)]})}function remove(id){patch({elements:elements.filter(e=>e.eid!==id)});if(id===selected)setSelected(null)}function onPointerDown(e,el,action='move'){if(e.pointerType==='mouse'&&e.button!==0)return;e.preventDefault();e.stopPropagation();setSelected(el.eid);try{e.currentTarget.setPointerCapture(e.pointerId)}catch{}const rect=board.current.getBoundingClientRect();drag.current={eid:el.eid,pointerId:e.pointerId,action,startX:e.clientX,startY:e.clientY,x:el.x,y:el.y,w:el.w,boardW:rect.width,boardH:rect.height}}function onPointerMove(e){const d=drag.current;if(!d||d.pointerId!==e.pointerId)return;e.preventDefault();e.stopPropagation();if(d.action==='resize'){updateEl(d.eid,{w:Math.max(8,Math.min(85,d.w+(e.clientX-d.startX)/d.boardW*100))})}else{updateEl(d.eid,{x:Math.max(0,Math.min(100,d.x+(e.clientX-d.startX)/d.boardW*100)),y:Math.max(0,Math.min(95,d.y+(e.clientY-d.startY)/d.boardH*100))})}}function onPointerUp(e){if(drag.current&&e.pointerId===drag.current.pointerId)drag.current=null}return <><div className="heading studio-heading studio-editor-head"><button className="ghost" onClick={onBack}><ArrowLeft size={18}/> 목록</button><strong className="studio-editor-title">{data.title||'새 코디'}</strong><div className="studio-buttons"><button className="studio-icon-action" onClick={()=>patch({favorite:!data.favorite})} aria-label={data.favorite?'즐겨찾기 해제':'즐겨찾기'} title="즐겨찾기"><Heart size={18} fill={data.favorite?'#9873c8':'none'} color="#9873c8"/></button><button className="studio-icon-action" onClick={()=>setMoreOpen(x=>!x)} aria-label="코디 더보기" aria-expanded={moreOpen}><MoreHorizontal size={18}/></button><button className="primary studio-save" disabled={busy} onClick={()=>onSave(data)}><Save size={16}/> 저장</button></div></div>
{moreOpen&&<div className="studio-more-menu"><button onClick={()=>{setDetailsOpen(true);setMoreOpen(false)}}><Pencil size={15}/> 코디 정보 수정</button><button onClick={()=>{setMoreOpen(false);data.id?onDuplicate(data):alert('먼저 저장해 주세요.')}}><Copy size={15}/> 코디 복제</button>{data.id&&<button onClick={async()=>{setMoreOpen(false);setExportBusy(true);try{await downloadOutfitPng(data,items,urls)}catch(e){message(e)}finally{setExportBusy(false)}}} disabled={exportBusy}><Download size={15}/> PNG 다운로드</button>}{data.id&&<button className="studio-danger" onClick={()=>{setMoreOpen(false);onDelete(data)}}><Trash2 size={15}/> 코디 삭제</button>}</div>}
<div className="mode-switch"><button className={mode==='slots'?'current':''} onClick={()=>setMode('slots')}><Grid2X2 size={17}/> 슬롯 조합</button><button className={mode==='canvas'?'current':''} onClick={()=>setMode('canvas')}><Move size={17}/> 자유 캔버스</button></div>{mode==='slots'?<><div className="slot-grid">{CATEGORIES.filter(cat=>allSlots||['아우터','상의','하의','신발'].includes(cat)||joined.some(el=>el.item?.category===cat)).map(cat=><div className={"slot "+(joined.some(el=>el.item?.category===cat)?"slot-filled":"slot-vacant")} key={cat}><div className="slot-head"><strong>{cat}</strong><button onClick={()=>{setFilter(cat);setAddOpen(true)}}><Plus size={16}/> 추가</button></div><div className="slot-images">{joined.filter(x=>x.item?.category===cat).map(e=><div className="slot-piece" key={e.eid}>{urls[e.item.id]?<img src={urls[e.item.id]} alt={e.item.title}/>:<Shirt/>}<small>{e.item.title}</small><button aria-label="제거" onClick={()=>remove(e.eid)}><X size={14}/></button></div>)}{!joined.some(x=>x.item?.category===cat)&&<span className="slot-empty"><Plus size={16}/> 아이템 선택</span>}</div></div>)}</div><button className="studio-show-slots" onClick={()=>setAllSlots(v=>!v)}>{allSlots?'기본 슬롯만 보기':'다른 슬롯 추가'} {allSlots?<ChevronUp size={15}/>:<ChevronDown size={15}/>}</button></>:<><p className="muted hint">사진을 드래그해 배치해 보세요. 선택한 사진은 아래에서 크기·각도·순서를 조절할 수 있어요.</p><div className="canvas-board" ref={board}>{joined.map(el=><div key={el.eid} className={'canvas-piece '+(selected===el.eid?'selected':'')} onPointerDown={e=>onPointerDown(e,el)} onPointerMove={onPointerMove} onPointerUp={onPointerUp} onPointerCancel={onPointerUp} style={{left:`${el.x}%`,top:`${el.y}%`,width:`${el.w}%`,zIndex:el.z,transform:`rotate(${el.rot}deg)`}}>{el.item&&urls[el.item.id]?<img draggable="false" src={urls[el.item.id]} alt={el.item.title}/>:<span>{el.item?.title||'삭제된 옷'}</span>}{selected===el.eid&&<div className="resize-handle" role="button" aria-label="아이템 크기 조절" onPointerDown={e=>onPointerDown(e,el,'resize')} onPointerMove={onPointerMove} onPointerUp={onPointerUp} onPointerCancel={onPointerUp}/>}</div>)}</div>{selectedEl&&<div className="canvas-controls"><strong>선택한 아이템: {items.find(i=>i.id===selectedEl.item_id)?.title||'없음'}</strong><label>크기 <input type="range" min="8" max="85" value={selectedEl.w} onChange={e=>updateEl(selected,{w:Number(e.target.value)})}/></label><label>회전 <input type="range" min="-180" max="180" value={selectedEl.rot} onChange={e=>updateEl(selected,{rot:Number(e.target.value)})}/></label><div className="row"><button className="secondary" onClick={()=>updateEl(selected,{z:Math.max(1,selectedEl.z-1)})}><ArrowDown size={16}/> 뒤로</button><button className="secondary" onClick={()=>updateEl(selected,{z:Math.max(...elements.map(x=>x.z),0)+1})}><ArrowUp size={16}/> 앞으로</button><button className="secondary" onClick={()=>updateEl(selected,{rot:0})}><RotateCcw size={16}/> 회전 초기화</button><button className="secondary" onClick={()=>remove(selected)}><Trash2 size={16}/> 제거</button></div></div>}<button className="secondary" onClick={()=>{setFilter('전체');setAddOpen(true)}}><Plus size={16}/> 캔버스에 아이템 추가</button></>}<div className="studio-work-actions"><button className="secondary" onClick={()=>{setFilter('전체');setPickerSearch('');setAddOpen(true)}}><Plus size={16}/> 보유 아이템</button><button className="secondary" onClick={()=>setRefPicker(true)}><Heart size={16}/> 잇걸룩 참고</button></div>
{activeReference&&<div className="inspiration-reference studio-reference"><img src={activeReference.imageUrl||referenceUrls[activeReference.id]} alt={activeReference.title}/><div><strong>{activeReference.title}</strong><small>{[activeReference.occasion,activeReference.season,activeReference.main_color,activeReference.main_item].filter(Boolean).join(' · ')}</small><p>{activeReference.notes}</p><button type="button" onClick={()=>setActiveReference(null)}><X size={14}/> 참고 닫기</button></div></div>}
<div className="studio-details"><button type="button" className="studio-details-toggle" onClick={()=>setDetailsOpen(v=>!v)} aria-expanded={detailsOpen}><strong>코디 정보</strong><small>{[data.occasion,data.season,(data.notes||'').trim()?'메모 있음':''].filter(Boolean).join(' · ')}</small>{detailsOpen?<ChevronUp size={17}/>:<ChevronDown size={17}/>}</button>
{detailsOpen&&<div className="studio-meta studio-meta-collapsed"><label>코디 이름<input aria-label="코디 이름" value={data.title} onChange={e=>patch({title:e.target.value})} placeholder="코디 이름"/></label><div className="two"><label>상황 / TPO<input aria-label="상황" placeholder="데이트·출근 등" value={data.occasion||''} onChange={e=>patch({occasion:e.target.value})}/></label><label>계절<select value={data.season||'사계절'} onChange={e=>patch({season:e.target.value})}>{['사계절','봄','여름','가을','겨울'].map(x=><option key={x}>{x}</option>)}</select></label></div><label className="notes-label">코디 메모<textarea rows={2} value={data.notes||''} onChange={e=>patch({notes:e.target.value})} placeholder="조합한 이유, 스타일링 아이디어 등"/></label><button type="button" className="primary" disabled={busy} onClick={()=>onSave(data)} style={{width:"100%",marginTop:12}}><Save size={16}/> 변경사항 저장</button></div>}</div>{refPicker&&<div className="overlay" onClick={()=>setRefPicker(false)}><div className="modal" onClick={e=>e.stopPropagation()}><div className="heading"><h2>참고 코디 선택</h2><button className="iconbtn" onClick={()=>setRefPicker(false)} aria-label="닫기"><X/></button></div><div className="reference-picker">{[...references.map(r=>({...r,imageUrl:referenceUrls[r.id],fromInspiration:true})),...realizationRefs.map(r=>({...r,fromRealization:true}))].map(r=><button key={(r.fromInspiration?'inspo:':'real:')+r.id} onClick={()=>{setActiveReference(r);patch({realizationId:r.fromRealization?r.id:null,title:data.title==='새 코디'?r.title:data.title,season:r.season||data.season,occasion:r.occasion||data.occasion});setRefPicker(false)}}>{r.imageUrl?<img src={r.imageUrl} alt={r.title||'참고 코디'}/>:<ImagePlus/>}<span>{r.title||'참고 코디'}</span><small>{r.fromInspiration?'잇걸룩':'실현 예정'}</small></button>)}</div>{!references.length&&!realizationRefs.length&&<p className="empty">아직 저장된 잇걸룩이나 실현 예정 코디가 없어.</p>}</div></div>}{addOpen&&<div className="overlay studio-picker-overlay" onClick={()=>setAddOpen(false)}><div className="modal studio-picker-sheet" onClick={e=>e.stopPropagation()} role="dialog" aria-label="보유 아이템 선택"><div className="heading studio-picker-head"><h2>아이템 추가 <small>{elements.length}개 선택됨</small></h2><button className="iconbtn" aria-label="아이템 선택 닫기" onClick={()=>setAddOpen(false)}><X/></button></div><div className="studio-picker-controls"><div className="search"><Search size={16}/><input value={pickerSearch} onChange={e=>setPickerSearch(e.target.value)} placeholder="아이템 이름·브랜드 검색" aria-label="아이템 검색"/></div><select value={filter} aria-label="아이템 카테고리" onChange={e=>setFilter(e.target.value)}>{['전체',...CATEGORIES].map(x=><option key={x}>{x}</option>)}</select></div><div className="picker-grid">{items.filter(i=>(filter==='전체'||i.category===filter)&&(!pickerSearch||[i.title,i.brand,i.color,i.subcategory].some(v=>String(v||'').toLowerCase().includes(pickerSearch.trim().toLowerCase())))).map(i=><button key={i.id} onClick={()=>add(i)}>{urls[i.id]?<img src={urls[i.id]} alt={i.title}/>:<Shirt size={30}/>}<span>{i.title}</span></button>)}</div>{!items.length&&<p className="empty">먼저 인벤토리에 옷을 등록해 주세요.</p>}<button type="button" className="primary studio-picker-done" onClick={()=>setAddOpen(false)}>선택 완료 · {elements.length}개</button></div></div>}</>}
export default App;

